INSERT INTO ev_faq (category, question, answer, sort_order, is_published) VALUES
('charging','Как найти подходящую зарядную станцию для моей Tesla?','На карте tesla.bosh.kg выберите автомобиль и используемые разъёмы. Учитывайте не только форму разъёма, но и рынок автомобиля, поддержку DC-зарядки и наличие необходимых доработок. Перед поездкой проверьте актуальный статус станции и подготовьте запасной вариант.',10,1),
('charging','Почему станция отображается свободной, но зарядка не запускается?','Статус оператора может обновляться с задержкой. Возможны неисправность конкретного порта, ошибка авторизации или оплаты, несовместимость протокола и адаптера либо ограничение автомобиля. Проверьте сообщение об ошибке на станции и в автомобиле, попробуйте другой исправный порт и сообщите оператору. Не повторяйте подключение при перегреве или повреждении контактов.',20,1),
('charging','Где зарядиться по дороге на Иссык-Куль?','Перед выездом откройте карту станций и отфильтруйте зарядки по вашим разъёмам. Проверьте доступность, мощность, рабочее состояние и варианты оплаты. Рассчитывайте поездку с запасом энергии и альтернативной остановкой: наличие точки на карте не гарантирует её работоспособность в момент прибытия.',30,1),
('adapters','Чем отличаются NACS, CCS2 и GB/T?','Это разные стандарты зарядных соединителей и обмена данными. NACS используется на многих североамериканских Tesla, CCS2 распространён в Европе, GB/T — в Китае. Совместимость определяется не одним лишь внешним разъёмом: имеет значение протокол зарядки, региональная версия автомобиля и возможный ретрофит.',10,1),
('adapters','Можно ли быстро заряжать американскую Tesla через GB/T-переходник?','Нельзя считать любую такую комбинацию безопасной и совместимой. В группе владельцы сообщали о серьёзных неисправностях после применения отдельных адаптеров, особенно на старых Model S/X. Проверьте точную модель, год, регион, поддержку DC и технические требования конкретного адаптера; перед первым использованием проконсультируйтесь с профильным специалистом.',20,1),
('adapters','Что такое ретрофит CCS и нужен ли он?','Ретрофит — аппаратная и/или программная доработка автомобиля для поддержки определённого типа быстрой зарядки. Необходимость зависит от модели, года, аппаратной конфигурации и рынка. Сам переходник не заменяет отсутствующую поддержку протокола. Проверять необходимость доработки следует по конкретному VIN и конфигурации.',30,1),
('adapters','Что выбрать: переходник или замену зарядного порта?','Универсального ответа нет. Переходник может подойти для периодических поездок, а переоборудование порта — при регулярном использовании конкретной инфраструктуры. Сравните подтверждённую совместимость, безопасность, стоимость и квалификацию установщика. Непроверенные адаптеры и самостоятельные переделки высоковольтной системы недопустимы.',40,1),
('battery','Как проверить состояние батареи Tesla (SOH)?','Отображаемый запас хода при 100% — не прямое измерение SOH. Для оценки здоровья аккумулятора применяют диагностические данные и предусмотренные производителем процедуры проверки батареи, с учётом температуры, условий измерения и комплектации. Интерпретацию данных лучше доверить специалисту, если есть ошибки BMS или резкое изменение поведения.',10,1),
('battery','Почему после зарядки до 100% Tesla показывает меньше километров, чем раньше?','Расчётный запас хода может изменяться из-за оценки доступной ёмкости системой BMS, температуры и калибровки. Одно показание само по себе не доказывает неисправность. Сравните значения в одинаковых условиях, проверьте наличие ошибок и при устойчивом существенном изменении проведите диагностику батареи.',20,1),
('battery','Как рассчитать запас хода на трассе?','Ориентируйтесь на фактический расход в кВт·ч/100 км именно вашего автомобиля, доступную энергию батареи и запас на непредвиденные обстоятельства. Скорость, температура, ветер, рельеф, отопление и кондиционер заметно влияют на расход. Для поездок вне города закладывайте резерв и не полагайтесь исключительно на номинальный пробег.',30,1),
('battery','Почему быстрая зарядка идёт медленно?','Мощность зависит от состояния заряда, температуры батареи, ограничений конкретной станции, распределения мощности между портами и совместимости оборудования. При холодной батарее или высоком проценте заряда снижение мощности может быть нормальным. При внезапных отключениях проверьте ошибки и обратитесь к оператору или в сервис.',40,1),
('service','Где найти специалиста по ремонту Tesla в Кыргызстане?','Ищите сервис с подтверждённым опытом работы именно с вашей моделью и конкретным узлом. Перед ремонтом попросите диагностику, письменную смету и информацию о гарантии на работы и детали. Для высоковольтной системы особенно важны обучение персонала и соответствующее оборудование.',10,1),
('service','Как правильно подбирать рычаги, подвеску и другие запчасти?','Сверяйте совместимость по VIN, модели, году и модификации; внешне похожие детали могут различаться. Уточните производителя, оригинальность, состояние детали и гарантию. Не ориентируйтесь только на описание «подходит на Model 3/Y» в объявлении.',20,1),
('service','Нужно ли менять масло в редукторе Tesla?','Регламент и конструкция трансмиссии зависят от модели, года и типа привода. Не следует применять общий совет о периодичности или составе масла ко всем Tesla. Используйте официальную техническую документацию конкретного автомобиля и сервис, знакомый с электроприводом.',30,1),
('software','Почему не работает приложение Tesla или привязка телефона?','Проверьте интернет в телефоне и автомобиле, авторизацию, права доступа и актуальность приложения. Bluetooth-ключ и дистанционные функции работают по разным механизмам. Если речь о переносе автомобиля в аккаунт, могут понадобиться подтверждение владения и поддержка Tesla.',10,1),
('software','Что делать, если Bluetooth перестал подключаться?','Попробуйте выключить и включить Bluetooth на телефоне, проверить разрешения приложения, удалить старое сопряжение и создать его заново. Перезапуск экрана автомобиля иногда помогает при временном сбое. Если проблема повторяется, проверьте сообщения системы и обратитесь к специалисту.',20,1),
('software','Что такое сертификаты Tesla и почему с ними возникают вопросы?','Под словом «сертификаты» владельцы могут иметь в виду разные механизмы доступа к подключённым функциям и сервисному оборудованию. Сначала уточните конкретное сообщение об ошибке, регион автомобиля и недоступную функцию. Не используйте непроверенные методы обхода защиты: они могут нарушить безопасность и работоспособность систем.',30,1),
('software','Работает ли FSD в Кыргызстане?','Доступность и набор функций помощи водителю зависят от аппаратной конфигурации, программного обеспечения, подписки, региона и действующих ограничений Tesla. Проверяйте функции на самом автомобиле и в официальной информации. Даже при активных возможностях водитель обязан постоянно контролировать движение.',40,1),
('home','Можно ли заряжать Tesla от обычной домашней розетки?','Возможность зависит от исправности заземления, состояния проводки, защиты линии, допустимой непрерывной нагрузки и оборудования зарядки. Не подключайте высокую длительную нагрузку через случайные удлинители или повреждённые розетки. Перед регулярной зарядкой попросите квалифицированного электрика проверить линию.',10,1),
('home','Как выбрать домашнюю зарядную станцию?','Уточните доступную мощность электросети, тип подключения, стандарт разъёма машины, требования защиты и возможные ограничения парковки. Монтаж должен выполнять квалифицированный специалист с соблюдением местных норм. Сначала оцените электросеть, затем подбирайте оборудование.',20,1),
('buying','Как проверить подержанную Tesla перед покупкой?','Проверьте VIN и историю повреждений, документы, фактическое состояние кузова, батареи, зарядного порта, подвески, программных функций и ошибок автомобиля. Заявленный пробег и сведения продавца следует сопоставлять с независимыми источниками. Особенно тщательно проверяйте машины после серьёзных ДТП или длительного хранения разряженными.',10,1),
('buying','Можно ли изменить пробег Tesla и как это проверить?','Не следует считать пробег на экране гарантированно неподдельным. Сравните историю аукционов, обслуживания, техосмотров и другие доступные записи с состоянием автомобиля и диагностикой. Расхождения — повод для дополнительной независимой проверки.',20,1),
('buying','Как рассчитать растаможку электромобиля в Кыргызстане?','Сумма зависит от действующих правил, квот, характеристик автомобиля и даты оформления. Информация из чата могла устареть. До оплаты покупки проверьте условия по официальным источникам и получите расчёт по документам конкретного автомобиля.',30,1),
('other','Как подобрать размер шин и дисков для Tesla?','Проверяйте штатные размеры именно для вашей модели, модификации и комплектации, а также нагрузочный и скоростной индексы, параметры диска и совместимость с тормозами. Неподходящая размерность может ухудшить управляемость и повлиять на показания системы.',10,1);
